# coding=UTF-8
# ex:ts=4:sw=4:et=on
#
# Typographic cross-section diagram for a MudLab Component.
# All output uses UTF-8 characters and CRLF line endings (Windows-safe).

_CRLF = "\r\n"
_SEP  = "═" * 52          # major boundary line
_MID  = "─" * 52          # zone separator

# Gap between consecutive atom z-values that triggers a new structural zone.
# 0.07 nm separates the tet / oct clusters cleanly for all known default
# components without splitting individual zones.
_GAP_NM = 0.07


def _cluster_layer_atoms(atoms):
    """
    Group layer atoms (sorted by default_z ascending) into clusters separated
    by z-gaps > _GAP_NM.  Returns list-of-lists, ordered bottom→top.
    """
    if not atoms:
        return []
    ordered = sorted(atoms, key=lambda a: a.default_z)
    clusters = [[ordered[0]]]
    for atom in ordered[1:]:
        if atom.default_z - clusters[-1][-1].default_z > _GAP_NM:
            clusters.append([])
        clusters[-1].append(atom)
    return clusters


def _zone_label(cluster):
    """
    Return a structural-zone label for a cluster, or '' for pure O/OH layers.
    Uses atom_type name prefixes to identify Si (tet) vs Al/Mg/Fe/Cr (oct).
    """
    names = [
        (a.atom_type.name if a.atom_type else "").upper()
        for a in cluster
    ]
    has_si  = any(n.startswith("SI")  for n in names)
    has_oct = any(
        any(n.startswith(x) for x in ("AL", "MG", "FE", "CR", "NI", "ZN", "CU"))
        for n in names
    )
    if has_si:
        return "TETRAHEDRAL SHEET"
    if has_oct:
        return "OCTAHEDRAL SHEET"
    return ""   # boundary / surface oxygens / hydroxyls — no zone label


_NAME_WIDTH = 14   # atom name column width in the diagram

def _pn_str(pn):
    """Format pn: integer-valued floats as '6.0', others as '3.500'."""
    if pn == int(pn):
        return "%.1f" % pn
    return "%.3f" % pn

def _name(atom):
    """Return atom name truncated to _NAME_WIDTH-1 chars to preserve column alignment."""
    n = atom.name or "?"
    return n if len(n) < _NAME_WIDTH else n[:_NAME_WIDTH - 1] + "…"  # ellipsis


def _interlayer_label(atoms, relations):
    """Build a short summary of interlayer contents from atom relations."""
    parts = []
    for rel in relations:
        rtype = type(rel).__name__
        if rtype == "AtomContents" and rel.enabled:
            parts.append("%s = %s" % (rel.name, _pn_str(rel.value)))
        elif rtype == "AtomRatio" and rel.enabled:
            a1 = rel.atom1
            a2 = rel.atom2
            if a1 and a2 and len(a1) >= 2 and len(a2) >= 2:
                n1 = a1[0].name if hasattr(a1[0], "name") else "?"
                n2 = a2[0].name if hasattr(a2[0], "name") else "?"
                parts.append(
                    "%s  %s:%s = %.0f:%.0f" % (
                        rel.name, n1, n2,
                        rel.value * 10, (1 - rel.value) * 10,
                    )
                )
    return "  |  ".join(parts) if parts else ""


def build_structure_diagram(component):
    """
    Generate a UTF-8 typographic cross-section diagram for *component*.

    Returns a string with CRLF line endings, ready for display in a
    GtkTextView.  Values are taken from the live model state — call this
    after atom relations have been applied.
    """
    d001      = component.d001
    default_c = component.default_c

    layer_atoms = list(component.layer_atoms)
    inter_atoms = list(component.interlayer_atoms)
    relations   = list(component.atom_relations)

    # lattice_d: runtime max Def.Z of layer atoms
    lattice_d = max((a.default_z for a in layer_atoms), default=0.0)

    # z_factor for interlayer stretch
    denom = default_c - lattice_d
    z_factor = (d001 - lattice_d) / denom if denom > 1e-9 else 1.0

    def calc_z(atom):
        return lattice_d + (atom.default_z - lattice_d) * z_factor

    # Identify the phase name if available
    try:
        phase_name = component.phase.name
    except AttributeError:
        phase_name = ""

    L = []   # output lines

    # ── header ────────────────────────────────────────────────────────────
    L.append(_SEP)
    title = "  %s" % component.name
    if phase_name:
        title += "   [phase: %s]" % phase_name
    L.append(title)
    L.append(_SEP)
    L.append("")

    # ── cluster & label the T-O-T layer ───────────────────────────────────
    clusters = _cluster_layer_atoms(layer_atoms)
    # Count how many TETRAHEDRAL SHEET clusters exist → 1:1 vs 2:1
    tet_clusters = [c for c in clusters if _zone_label(c) == "TETRAHEDRAL SHEET"]
    n_tet = len(tet_clusters)   # 1 → 1:1 clay; 2 → 2:1 clay

    tet_labels = []
    if n_tet >= 2:
        tet_labels = ["LOWER TETRAHEDRAL SHEET", "UPPER TETRAHEDRAL SHEET"]
    elif n_tet == 1:
        tet_labels = ["TETRAHEDRAL SHEET"]

    tet_idx = 0   # pointer into tet_labels

    # ── top annotation ────────────────────────────────────────────────────
    L.append("           ← bottom of adjacent layer")
    L.append("")

    # ── d001 boundary ─────────────────────────────────────────────────────
    L.append("z = %.4f nm  %s  d001" % (d001, _SEP[:22]))
    L.append("")

    # ── interlayer zone ───────────────────────────────────────────────────
    if inter_atoms:
        il_sorted = sorted(inter_atoms, key=calc_z, reverse=True)

        il_summary = _interlayer_label(inter_atoms, relations)
        L.append("  \xb7  INTERLAYER")
        if il_summary:
            L.append("  \xb7  %s" % il_summary)
        L.append("  \xb7")

        for atom in il_sorted:
            cz       = calc_z(atom)
            type_str = atom.atom_type.name if atom.atom_type else "?"
            L.append("z = %.4f nm  \xb7  %-14s  pn = %-7s  %s" % (
                cz, _name(atom), _pn_str(atom.pn), type_str))

        L.append("")
    else:
        L.append("  │  (no interlayer — charge-neutral or structural)")
        L.append("")

    # ── lattice_d boundary ────────────────────────────────────────────────
    L.append("z = %.4f nm  %s  lattice_d" % (lattice_d, _SEP[:22]))

    # ── layer zone: clusters top → bottom ────────────────────────────────
    for cluster in reversed(clusters):
        label = _zone_label(cluster)

        # Zone separator + label
        if label == "TETRAHEDRAL SHEET":
            actual_label = tet_labels[-(tet_idx + 1)] if tet_labels else label
            tet_idx += 1
            L.append("  │  %s  %s" % (_MID[:4], actual_label))
        elif label == "OCTAHEDRAL SHEET":
            # Build oct composition summary
            oct_parts = []
            for a in sorted(cluster, key=lambda x: x.default_z):
                type_str = a.atom_type.name if a.atom_type else "?"
                if not (type_str.startswith("O") or type_str.startswith("OH")):
                    oct_parts.append("%s pn=%s" % (a.name, _pn_str(a.pn)))
            total_oct = sum(a.pn for a in cluster
                            if a.atom_type and
                            not a.atom_type.name.startswith(("O", "H")))
            oct_str = "  +  ".join(oct_parts)
            if total_oct > 0:
                n_sites = int(round(total_oct))
                octy = "dioctahedral" if n_sites <= 4 else "trioctahedral"
                oct_str += "   (%s, %d sites/uc)" % (octy, n_sites)
            L.append("  │  %s  OCTAHEDRAL SHEET  —  %s" % (_MID[:4], oct_str))
        else:
            L.append("  │")

        # Atom lines for this cluster (top → bottom within cluster)
        for atom in sorted(cluster, key=lambda a: a.default_z, reverse=True):
            type_str = atom.atom_type.name if atom.atom_type else "?"
            L.append("z = %.4f nm  │  %-14s  pn = %-7s  %s" % (
                atom.default_z, _name(atom), _pn_str(atom.pn), type_str))

    # ── z = 0 boundary ────────────────────────────────────────────────────
    L.append("")
    L.append("z = 0.0000 nm  %s  z = 0" % _SEP[:22])
    L.append("")
    L.append("           ← top of adjacent layer below")
    L.append("")

    # ── charge balance ────────────────────────────────────────────────────
    try:
        layer_q, inter_q, net = component.compute_charge_balance()
        L.append(_SEP)
        L.append("  Charge balance (per unit cell):")
        L.append("    Layer:       %+.3f" % layer_q)
        L.append("    Interlayer:  %+.3f" % inter_q)
        balance = "✓ balanced" if abs(net) <= 0.05 else "⚠ imbalanced"
        L.append("    Net:         %+.3f   %s" % (net, balance))
        L.append(_SEP)
    except Exception:
        pass

    return _CRLF.join(L)
